package com.gangchil.counter;
import android.app.*;import android.os.*;import android.content.*;import android.bluetooth.*;import android.hardware.usb.*;import android.graphics.*;import android.text.*;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
public class QueueService extends Service {
 android.content.SharedPreferences prefs;ScheduledExecutorService worker;String mode,device;boolean testing=false;Pipe livePipe;String liveDevice="";
 public void onCreate(){super.onCreate();prefs=getSharedPreferences("counter",0);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("printer","Gangchil receipt printing",NotificationManager.IMPORTANCE_LOW));startForeground(1,new Notification.Builder(this,"printer").setContentTitle("Gangchil printer active").setContentText("Receiving shared receipt jobs").setSmallIcon(android.R.drawable.stat_sys_upload).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setOngoing(true).build());worker=Executors.newSingleThreadScheduledExecutor();worker.scheduleWithFixedDelay(()->tick(),1,5,TimeUnit.SECONDS);}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"WAKE".equals(i.getAction()))worker.execute(()->tick());if(i!=null&&"TEST".equals(i.getAction()))worker.execute(()->{try{if(prefs.contains("active"))throw new Exception("Finish or resolve the active receipt first");JSONObject o=new JSONObject().put("id",0).put("table_label","TEST").put("total","123.45");JSONArray items=new JSONArray().put(new JSONObject().put("product_name","Test receipt · বাংলা").put("quantity",1).put("unit_price",123.45));mode=prefs.getString("mode","bt");device=prefs.getString("device","");print(render(o,items));status("Test sent. Check the paper.");}catch(Exception e){status(e.getMessage());}});return START_STICKY;}
 public IBinder onBind(Intent i){return null;}
 void status(String value){prefs.edit().putString("status",value).commit();}
 JSONObject call(String route,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(MainActivity.SITE+"/staff/api/printing/worker/"+route).openConnection();try{c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("X-Print-Token",prefs.getString("token",""));c.setRequestProperty("User-Agent",prefs.getString("ua","Gangchil"));c.setRequestProperty("Cookie",prefs.getString("cookie",""));c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(in!=null)try(InputStream read=in){byte[] buf=new byte[4096];int n;while((n=read.read(buf))>0){bytes.write(buf,0,n);if(bytes.size()>1000000)throw new Exception("Server response too large");}}JSONObject result;try{result=new JSONObject(bytes.toString("UTF-8"));}catch(Exception e){throw new Exception("Hosting verification required. Open Gangchil app again.");}if(code==401||code==403)prefs.edit().remove("token").commit();if(code>=400)throw new Exception(result.optString("error","Server request failed"));return result;}finally{c.disconnect();}}
 void save(JSONObject job)throws Exception{if(!prefs.edit().putString("active",job.toString()).commit())throw new Exception("Could not save receipt recovery state");}
 void finish(JSONObject job,String result)throws Exception{call("result",new JSONObject().put("id",job.getLong("id")).put("claim",job.getString("claim")).put("status",result).put("detail",result.equals("unknown")?"Delivery uncertain. Check paper before retrying.":""));prefs.edit().remove("active").commit();}
 void tick(){PowerManager.WakeLock lock=null;try{if(!prefs.contains("printer"))return;if(!prefs.contains("token")){status("Open Printer setup to enable automatic printing");return;}lock=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Gangchil:receipt");lock.acquire(120000);mode=prefs.getString("mode","bt");device=prefs.getString("device","");
 if(prefs.contains("active")){JSONObject old=new JSONObject(prefs.getString("active","{}"));if(old.optString("stage").equals("submitted"))finish(old,"submitted");else {call("recover",new JSONObject().put("id",old.getLong("id")).put("claim",old.getString("claim")));prefs.edit().remove("active").commit();}}
 // Do not claim while the configured transport is absent.
 if(mode.equals("bt")){BluetoothAdapter bt=getSystemService(BluetoothManager.class).getAdapter();if(bt==null||!bt.isEnabled())throw new Exception("Bluetooth is off");}else{UsbManager um=getSystemService(UsbManager.class);UsbDevice d=um.getDeviceList().get(device);if(d==null||!um.hasPermission(d))throw new Exception("USB printer disconnected");}
 ensurePipe();heartbeat(true);JSONObject answer=call("claim",new JSONObject());JSONObject job=answer.optJSONObject("job");if(job==null){status(answer.optBoolean("blocked")?"Receipt needs paper check in Printer settings":"Printer selected · "+prefs.getString("printer",""));return;}
 byte[] payload=render(job.getJSONObject("order"),job.getJSONArray("items"));try{Pipe pipe=ensurePipe();job.put("stage","dispatching");save(job);
 call("begin",new JSONObject().put("id",job.getLong("id")).put("claim",job.getString("claim")));
 try{pipe.write(payload);job.put("stage","submitted");save(job);}catch(Exception e){job.put("stage","unknown");save(job);finish(job,"unknown");throw e;}
 finish(job,"submitted");status("Receipt sent · #"+job.getLong("order_id"));}catch(Exception e){if(!prefs.contains("active"))call("recover",new JSONObject().put("id",job.getLong("id")).put("claim",job.getString("claim")));throw e;}
 }catch(Exception e){disconnect();try{if(prefs.contains("token"))heartbeat(false);}catch(Exception ignored){}status(e.getMessage());}finally{if(lock!=null&&lock.isHeld())lock.release();}}
 byte[] render(JSONObject order,JSONArray items)throws Exception{
 StringBuilder text=new StringBuilder("GANGCHIL\nCash receipt\n────────────────────\nOrder #");text.append(String.format(Locale.US,"%06d",order.getLong("id"))).append("\nTable ").append(order.optString("table_label")).append("\n").append(order.optString("paid_at","")).append("\n────────────────────\n");
 for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);int qty=item.getInt("quantity");double price=item.getDouble("unit_price");text.append(item.getString("product_name")).append("\n").append(String.format(Locale.US,"%d × BDT %.2f = %.2f\n\n",qty,price,qty*price));}
 text.append("────────────────────\nTOTAL BDT ").append(order.getString("total")).append("\n\nThank you for visiting!\n");TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.BLACK);paint.setTextSize(21);paint.setTypeface(Typeface.createFromAsset(getAssets(),"HindSiliguri-Regular.ttf"));StaticLayout layout=StaticLayout.Builder.obtain(text,0,text.length(),paint,360).setAlignment(Layout.Alignment.ALIGN_NORMAL).setLineSpacing(5,1).setIncludePad(true).build();int h=layout.getHeight()+48;if(h>6000)throw new Exception("Receipt too long");Bitmap bitmap=Bitmap.createBitmap(384,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);canvas.translate(12,12);layout.draw(canvas);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(new byte[]{27,64,27,97,0,27,51,24});for(int row=0;row<h;row+=24){out.write(new byte[]{27,42,33,(byte)128,1});for(int x=0;x<384;x++)for(int part=0;part<3;part++){int value=0;for(int bit=0;bit<8;bit++){int y=row+part*8+bit;if(y<h){int c=bitmap.getPixel(x,y);if(Color.red(c)*.2126+Color.green(c)*.7152+Color.blue(c)*.0722<160)value|=128>>bit;}}out.write(value);}out.write(10);}out.write(new byte[]{27,50,10,10,10});bitmap.recycle();return out.toByteArray();}
 class Pipe implements AutoCloseable {
 volatile boolean connected=true;BluetoothSocket socket;UsbDeviceConnection usb;UsbInterface face;UsbEndpoint endpoint;ScheduledExecutorService timeout;
 void write(byte[] payload)throws Exception{ScheduledFuture<?> watchdog=timeout==null?null:timeout.schedule(()->close(),90,TimeUnit.SECONDS);try{if(socket!=null){OutputStream out=socket.getOutputStream();for(int off=0;off<payload.length;off+=128){out.write(payload,off,Math.min(128,payload.length-off));out.flush();Thread.sleep(12);}Thread.sleep(300);}else for(int off=0;off<payload.length;){int sent=usb.bulkTransfer(endpoint,payload,off,Math.min(256,payload.length-off),5000);if(sent<=0)throw new Exception("USB write failed");off+=sent;Thread.sleep(12);}}finally{if(watchdog!=null)watchdog.cancel(false);}}
 public void close(){connected=false;if(timeout!=null)timeout.shutdownNow();try{if(socket!=null)socket.close();}catch(Exception ignored){}if(usb!=null){if(face!=null)usb.releaseInterface(face);usb.close();}}
 }
 Pipe openPrinter()throws Exception{Pipe pipe=new Pipe();try{if(mode.equals("bt")){BluetoothAdapter adapter=getSystemService(BluetoothManager.class).getAdapter();if(adapter==null)throw new Exception("Bluetooth unavailable");pipe.socket=adapter.getRemoteDevice(device).createRfcommSocketToServiceRecord(UUID.fromString("00001101-0000-1000-8000-00805F9B34FB"));pipe.timeout=Executors.newSingleThreadScheduledExecutor();pipe.timeout.schedule(()->{try{pipe.socket.close();}catch(Exception ignored){}},12,TimeUnit.SECONDS);pipe.socket.connect();pipe.timeout.shutdownNow();pipe.timeout=Executors.newSingleThreadScheduledExecutor();Thread reader=new Thread(()->{try{InputStream in=pipe.socket.getInputStream();byte[] statusBytes=new byte[64];while(in.read(statusBytes)!=-1){}}catch(Exception ignored){}finally{pipe.connected=false;prefs.edit().putBoolean("connected",false).apply();}},"printer-connection");reader.setDaemon(true);reader.start();
 }else{UsbManager manager=getSystemService(UsbManager.class);UsbDevice selected=manager.getDeviceList().get(device);if(selected==null||!manager.hasPermission(selected))throw new Exception("USB permission/device missing");for(int i=0;i<selected.getInterfaceCount();i++){UsbInterface face=selected.getInterface(i);for(int j=0;j<face.getEndpointCount();j++){UsbEndpoint ep=face.getEndpoint(j);if(ep.getDirection()==UsbConstants.USB_DIR_OUT&&ep.getType()==UsbConstants.USB_ENDPOINT_XFER_BULK){pipe.face=face;pipe.endpoint=ep;break;}}if(pipe.endpoint!=null)break;}if(pipe.endpoint==null)throw new Exception("No USB printer interface");pipe.usb=manager.openDevice(selected);if(pipe.usb==null||!pipe.usb.claimInterface(pipe.face,true))throw new Exception("USB printer busy");}return pipe;}catch(Exception e){pipe.close();throw e;}}
 Pipe ensurePipe()throws Exception{String key=mode+":"+device;if(livePipe==null||!livePipe.connected||!key.equals(liveDevice)){disconnect();livePipe=openPrinter();liveDevice=key;}prefs.edit().putBoolean("connected",true).apply();return livePipe;}
 void disconnect(){if(livePipe!=null)livePipe.close();livePipe=null;prefs.edit().putBoolean("connected",false).apply();}
 void heartbeat(boolean online)throws Exception{call("heartbeat",new JSONObject().put("online",online));}
 void print(byte[] payload)throws Exception{try{ensurePipe().write(payload);}catch(Exception e){disconnect();throw e;}}
 public void onDestroy(){worker.shutdownNow();disconnect();super.onDestroy();}
}
